<?php require_once __DIR__.'/../config/bootstrap.php';
$action=$_GET['action']??'';$p=db();
if($action==='register'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf($_POST['csrf']??'');$email=trim($_POST['email']??'');$name=trim($_POST['name']??'');$pass=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6)json_response(['ok'=>false,'message'=>'邮箱或密码格式不正确']);$s=$p->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())json_response(['ok'=>false,'message'=>'该邮箱已注册']);$h=password_hash($pass,PASSWORD_DEFAULT);$s=$p->prepare('INSERT INTO users(email,name,password_hash,trial_started_at) VALUES(?,?,?,NOW())');$s->execute([$email,$name,$h]);$_SESSION['user_id']=$p->lastInsertId();json_response(['ok'=>true,'redirect'=>'index.php']);}
if($action==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf($_POST['csrf']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=$p->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($pass,$u['password_hash'])||$u['status']!=='active')json_response(['ok'=>false,'message'=>'账号或密码错误']);$_SESSION['user_id']=$u['id'];json_response(['ok'=>true,'redirect'=>'index.php']);}
if($action==='logout'){session_destroy();header('Location: ../index.php');exit;} json_response(['ok'=>false,'message'=>'无效请求'],400);
